package com.lianxibu.site.service.jobs;

import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.ReportInputSnapshotService.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

/** Complete original count universe, original source facts and native body associations share one final RR snapshot. */
public final class EntityHeatReportComponentService {
    private record Facts(List<Candidate> candidates,List<GenerationFlowService.Dependency> dependencies,Map<String,List<String>> targets,List<MissingInput> missing,Map<String,JdbcEntityHeatOriginHeaders.Header> headers,long bytes){ }
    public static final class Captured {
        private final Object issuer;private final EntityHeatCutoffProofService.Captured counts;private final EntityHeatSourceOriginService.Captured sources;private final Facts facts;private final boolean supplement;
        private Captured(Object issuer,EntityHeatCutoffProofService.Captured counts,EntityHeatSourceOriginService.Captured sources,Facts facts,boolean supplement){this.issuer=issuer;this.counts=counts;this.sources=sources;this.facts=facts;this.supplement=supplement;}
        public Instant cutoff(){return counts.cutoff();}public List<Candidate> candidates(){return facts.candidates();}public List<GenerationFlowService.Dependency> dependencies(){return facts.dependencies();}public Map<String,List<String>> referenceTargetsByEvidence(){return facts.targets();}public List<MissingInput> missing(){return facts.missing();}public long originalByteSize(){return facts.bytes();}
        @Override public String toString(){return "CompleteOriginalEntityHeatReportComponent[redacted]";}
    }
    private final Object issuer=new Object();private final EntityHeatCutoffProofService counts;private final EntityHeatSourceOriginService sources;private final JdbcEntityHeatOriginHeaders headers;private final TransactionTemplate reads;private final int budget;
    public EntityHeatReportComponentService(EntityHeatCutoffProofService counts,EntityHeatSourceOriginService sources,JdbcEntityHeatOriginHeaders headers,PlatformTransactionManager tx){this(counts,sources,headers,tx,EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES);}
    public EntityHeatReportComponentService(EntityHeatCutoffProofService counts,EntityHeatSourceOriginService sources,JdbcEntityHeatOriginHeaders headers,PlatformTransactionManager tx,int budget){this.counts=Objects.requireNonNull(counts);this.sources=Objects.requireNonNull(sources);this.headers=Objects.requireNonNull(headers);if(budget<1024||budget>EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES)throw invalid();this.budget=budget;reads=new TransactionTemplate(Objects.requireNonNull(tx));reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);}
    public Captured capture(Instant cutoff){if(TransactionSynchronizationManager.isActualTransactionActive())throw invalid();var original=counts.capture(cutoff);var source=sources.capture(required(original),cutoff);return reads.execute(s->new Captured(issuer,original,source,build(original,source,false),false));}
    /** Complete native facts at an explicit supplement cutoff; unknown original source remains an explicit gap. */
    public Captured captureSupplement(Instant cutoff){if(TransactionSynchronizationManager.isActualTransactionActive())throw invalid();var original=counts.captureSupplement(cutoff);var source=sources.capture(required(original),cutoff);return reads.execute(s->new Captured(issuer,original,source,build(original,source,true),true));}
    public Captured verifyObserved(Captured captured){readonly();if(captured==null||captured.issuer!=issuer||!captured.facts.equals(build(captured.counts,captured.sources,captured.supplement)))throw invalid();return captured;}
    private static Map<String,List<String>> touched(EntityHeatCutoffProofService.Captured original){var result=new TreeMap<String,List<String>>();original.counts().keySet().forEach(id->result.put(id,new ArrayList<>()));for(var event:original.originalEvents()){var decoded=EntityDecisionJdbcLog.decodeReceiptPayload(event.payloadJson(),event.reason());for(var snapshot:decoded.snapshots()){var list=result.get(snapshot.entityId());if(list!=null)list.add(event.id());}}return result;}
    private static Set<String> required(EntityHeatCutoffProofService.Captured original){var all=new HashSet<String>();touched(original).values().forEach(all::addAll);var ids=new TreeSet<String>();for(var event:original.originalEvents())if(all.contains(event.id())){var decoded=EntityDecisionJdbcLog.decodeReceiptPayload(event.payloadJson(),event.reason());if("entity-decision-v2".equals(decoded.schema())&&Set.of("new","existing","needs_review").contains(decoded.operation()))ids.add(event.id());}return ids;}
    private Facts build(EntityHeatCutoffProofService.Captured original,EntityHeatSourceOriginService.Captured source,boolean supplement){readonly();counts.verifyObserved(original);sources.verifyObserved(source);if(!original.cutoff().equals(source.cutoff())||!required(original).equals(source.requested()))throw invalid();long bytes=add(0,original.originalByteSize());bytes=add(bytes,source.originalByteSize());
        var missing=new ArrayList<MissingInput>();for(var gap:original.gaps())missing.add(new MissingInput("entity",gap.entityId(),null,gap.reason()));var candidates=new ArrayList<Candidate>();var dependencies=new TreeMap<String,GenerationFlowService.Dependency>();var targets=new TreeMap<String,List<String>>();var nativeHeaders=new TreeMap<String,JdbcEntityHeatOriginHeaders.Header>();var byEntity=touched(original);
        var leaves=new TreeMap<String,NewsSourceReportComponentService.EntityLeaf>();for(var day:source.days())for(var leaf:day.entityLeaves()){if(leaves.putIfAbsent(leaf.itemId(),leaf)!=null)throw invalid();var header=headers.read(leaf.itemId());nativeHeaders.put(leaf.itemId(),header);bytes=add(bytes,512L+size(header==null?null:header.sourceItemId()));if(header!=null&&(!header.runId().equals(leaf.runId())||!header.sourceId().equals(leaf.sourceId())||!header.sourceItemId().equals(leaf.sourceItemId())||!header.day().equals(leaf.day())||header.revision()<leaf.inputRevision()+2||header.createdAt().isAfter(original.cutoff())))throw invalid();}
        for(var entry:original.counts().entrySet()){String entity=entry.getKey();var ids=byEntity.get(entity);if(ids==null||ids.isEmpty()||!ids.contains(entry.getValue().eventId()))throw invalid();boolean qualified=true;for(String id:ids){var origin=source.origins().get(id);if(origin==null||!entity.equals(origin.entityId())){qualified=false;break;}}
            if(!qualified){missing.add(new MissingInput("entity",entity,null,"count_source_origin_unproven"));continue;}
            var possible=new ArrayList<NewsSourceReportComponentService.EntityLeaf>();for(var leaf:leaves.values())if(entity.equals(leaf.entityId())){var matching=ids.stream().map(source.origins()::get).filter(o->o.itemId().equals(leaf.itemId())).toList();if(matching.isEmpty())continue;for(var origin:matching)if(!origin.sourceId().equals(leaf.sourceId())||!origin.runId().equals(leaf.runId())||!origin.sourceItemId().equals(leaf.sourceItemId())||!origin.day().equals(leaf.day())||!origin.originalBodyHash().equals(leaf.bodyHash())||!origin.originalBodyJson().equals(leaf.bodyJson()))throw invalid();possible.add(leaf);}
            if(possible.isEmpty()){missing.add(new MissingInput("entity",entity,null,"entity_body_unproven"));continue;}
            possible.sort(Comparator.comparing((NewsSourceReportComponentService.EntityLeaf leaf)->eligible(leaf,nativeHeaders.get(leaf.itemId()))).reversed().thenComparing(NewsSourceReportComponentService.EntityLeaf::availableAt,Comparator.reverseOrder()).thenComparing(NewsSourceReportComponentService.EntityLeaf::itemId));var leaf=possible.getFirst();var header=nativeHeaders.get(leaf.itemId());boolean association=header!=null&&entity.equals(header.entityId());
            var combined=new NewsSourceReportComponentService.EntityLeaf(leaf.itemId(),leaf.entityId(),leaf.sourceId(),leaf.runId(),leaf.sourceItemId(),leaf.day(),leaf.rootId(),leaf.inputHash(),leaf.inputRevision(),leaf.bodyHash(),leaf.bodyJson(),leaf.title(),leaf.summary(),leaf.referenceJson(),leaf.validityRevision(),leaf.effectiveValid()&&header!=null&&header.effectiveValid(),leaf.blocked()||header==null||!Set.of("ready","analyzed").contains(header.state()),leaf.availableAt());
            var value=supplement?EntityHeatReportCandidate.createSupplement(entry.getValue(),combined,original.cutoff(),association):EntityHeatReportCandidate.create(entry.getValue(),combined,original.cutoff(),association);candidates.add(value.candidate());var previous=dependencies.putIfAbsent(value.dependency().id(),value.dependency());if(previous!=null&&!previous.equals(value.dependency()))throw invalid();if(targets.putIfAbsent(value.candidate().evidence().id(),List.of(value.referenceJson()))!=null)throw invalid();bytes=add(bytes,size(value.candidate().evidence().bodyJson())+size(value.referenceJson())+256L);
        }
        var headerFacts=Collections.unmodifiableMap(new LinkedHashMap<>(nativeHeaders));return new Facts(List.copyOf(candidates),List.copyOf(dependencies.values()),Collections.unmodifiableMap(targets),List.copyOf(missing),headerFacts,bytes);
    }
    private static boolean eligible(NewsSourceReportComponentService.EntityLeaf leaf,JdbcEntityHeatOriginHeaders.Header header){return leaf.effectiveValid()&&!leaf.blocked()&&header!=null&&leaf.entityId()!=null&&leaf.entityId().equals(header.entityId())&&header.effectiveValid()&&Set.of("ready","analyzed").contains(header.state());}
    private long add(long current,long next){long value=Math.addExact(current,next);if(value>budget)throw new GenerationFlowService.CapacityGuarded();return value;}
    private static long size(String value){return value==null?0:value.getBytes(StandardCharsets.UTF_8).length;}
    private static void readonly(){if(!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.isCurrentTransactionReadOnly()||!Integer.valueOf(TransactionDefinition.ISOLATION_REPEATABLE_READ).equals(TransactionSynchronizationManager.getCurrentTransactionIsolationLevel()))throw invalid();}
    private static IllegalStateException invalid(){return new IllegalStateException("complete native entity heat report component unavailable");}
}
